        moves = [[dx, 0], [0, dy], [dx, dy], [-dx, 0], [0, -dy]]
    else:
        dx = 1 if s[0] <= opp[0] else -1
        dy = 1 if s[1] <= opp[1] else -1
        if my < op:
            moves = [[dx, 0], [0, dy], [dx, dy], [-dx, 0], [0, -dy]]
        else:
